import type {
  Turnaround, AppliedDisruption, ScheduleResult, RecoveryPlan,
  SimulationReport, LedgerEntry, JevEvidence,
} from '@/types';

const DISCLAIMER =
  'SIMULATION ONLY — This report was generated by TurnaroundIQ using fictional data and a deterministic scheduling engine. ' +
  'It is not live airport operational data and must not be used for real-world flight planning or delay attribution.';

export function buildReport(
  turnaround: Turnaround,
  baseline: ScheduleResult,
  disruption: AppliedDisruption | null,
  disruptedSchedule: ScheduleResult,
  recoveryPlans: RecoveryPlan[],
  selectedPlanId: string | null,
  finalSchedule: ScheduleResult,
  jevEvidence: JevEvidence | null = null,
): SimulationReport {
  const selectedPlan = recoveryPlans.find((p) => p.id === selectedPlanId) ?? null;
  const baselineDelaySaved = selectedPlan
    ? Math.max(0, disruptedSchedule.departureDelay - finalSchedule.departureDelay)
    : 0;

  return {
    reportId: `RPT-${Date.now()}`,
    timestamp: new Date().toISOString(),
    disclaimer: DISCLAIMER,
    scenarioId: disruption?.scenarioId ?? 'none',
    scenarioName: disruption?.scenarioName ?? 'No disruption',
    turnaroundId: turnaround.id,
    flightNumber: turnaround.flightNumber,
    aircraftType: turnaround.aircraftType,
    gate: turnaround.gate,
    origin: turnaround.origin,
    destination: turnaround.destination,
    baseline: {
      estimatedDeparture: baseline.estimatedDeparture,
      departureDelay: baseline.departureDelay,
      status: baseline.status,
    },
    disruption: disruption
      ? {
          scenarioId: disruption.scenarioId,
          scenarioName: disruption.scenarioName,
          effects: disruption.effects,
        }
      : null,
    disruptedSchedule: {
      estimatedDeparture: disruptedSchedule.estimatedDeparture,
      departureDelay: disruptedSchedule.departureDelay,
      status: disruptedSchedule.status,
      affectedTaskCount: disruptedSchedule.affectedTaskIds.length,
      resourceConflictCount: disruptedSchedule.resourceConflicts.length,
    },
    recoveryPlans: recoveryPlans.map((p) => ({
      id: p.id,
      name: p.name,
      feasible: p.feasible,
      departureDelay: p.departureDelay,
      delaySaved: p.delaySaved,
      actions: p.actions,
      constraintErrors: p.constraintErrors,
    })),
    selectedPlanId,
    finalOutcome: {
      estimatedDeparture: finalSchedule.estimatedDeparture,
      departureDelay: finalSchedule.departureDelay,
      status: finalSchedule.status,
      delaySaved: baselineDelaySaved,
    },
    jevEvidence,
  };
}

export function exportReportJson(report: SimulationReport): void {
  const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${report.reportId}_${report.flightNumber}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

export function buildLedgerEntryReport(entry: LedgerEntry, turnaround: Turnaround): SimulationReport {
  return buildReport(
    turnaround,
    entry.baselineSchedule,
    entry.disruption,
    entry.disruptedSchedule,
    entry.recoveryPlans,
    entry.selectedPlanId,
    entry.finalSchedule,
    entry.jevEvidence,
  );
}
